// ---- misc helpers ----

func uuidv4() string {
	var b [16]byte
	rand.Read(b[:])
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	var s [36]byte
	hex.Encode(s[0:4], b[0:2])
	hex.Encode(s[4:8], b[2:4])
	s[8] = '-'
	hex.Encode(s[9:13], b[4:6])
	s[13] = '-'
	hex.Encode(s[14:18], b[6:8])
	s[18] = '-'
	hex.Encode(s[19:23], b[8:10])
	s[23] = '-'
	hex.Encode(s[24:36], b[10:16])
	return string(s[:])
}

func base64StdDecode(s string) ([]byte, error) { return base64.StdEncoding.DecodeString(s) }

// ---- OpenAI request types ----

type chatRequest struct {
	Model       string         `json:"model"`
	Messages    []oaiMessage   `json:"messages"`
	Stream      bool           `json:"stream"`
	Tools       []oaiTool      `json:"tools"`
	StreamOpts  *streamOptions `json:"stream_options"`
	MaxTokens   int            `json:"max_tokens"`
	MaxCompToks int            `json:"max_completion_tokens"`
	// Reasoning effort is an OpenAI parameter, not a model variant.
	// reasoning_effort wins over reasoning.effort when both are sent.
	ReasoningEffort string `json:"reasoning_effort"`
	Reasoning       *struct {
		Effort string `json:"effort"`
	} `json:"reasoning"`
}

func (r *chatRequest) effort() string {
	if r.ReasoningEffort != "" {
		return r.ReasoningEffort
	}
	if r.Reasoning != nil {
		return r.Reasoning.Effort
	}
	return ""
}

type streamOptions struct {
	IncludeUsage bool `json:"include_usage"`
}

type oaiTool struct {
	Type     string          `json:"type"`
	Function oaiToolFunction `json:"function"`
}

type oaiToolFunction struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	Parameters  json.RawMessage `json:"parameters"`
}

type oaiMessage struct {
	Role             string          `json:"role"`
	Content          json.RawMessage `json:"content"` // string | [{type,text|image_url}]
	ReasoningContent string          `json:"reasoning_content,omitempty"`
	ToolCalls        []oaiToolCall   `json:"tool_calls,omitempty"`
	ToolCallID       string          `json:"tool_call_id,omitempty"`
	Name             string          `json:"name,omitempty"`
}

type oaiToolCall struct {
	ID       string `json:"id"`
	Type     string `json:"type"`
	Function struct {
		Name      string `json:"name"`
		Arguments string `json:"arguments"`
	} `json:"function"`
	Index int `json:"index,omitempty"` // stream-side
}

// contentBlock flattens OpenAI content into text + inline images.
type contentBlock struct {
	text   string
	images [][2]string // {b64, mime}
}

func flattenContent(raw json.RawMessage) contentBlock {
	var s string
	if json.Unmarshal(raw, &s) == nil {
		return contentBlock{text: s}
	}
	var parts []struct {
		Type     string `json:"type"`
		Text     string `json:"text"`
		ImageURL *struct {
			URL string `json:"url"`
		} `json:"image_url"`
	}
	var out contentBlock
	if json.Unmarshal(raw, &parts) != nil {
		return out
	}
	var texts []string
	for _, p := range parts {
		switch p.Type {
		case "text":
			texts = append(texts, p.Text)
		case "image_url", "input_image":
			u := ""
			if p.ImageURL != nil {
				u = p.ImageURL.URL
			}
			if i := strings.Index(u, ";base64,"); i >= 0 && strings.HasPrefix(u, "data:") {
				mime := u[5:i]
				out.images = append(out.images, [2]string{u[i+8:], mime})
			}
		}
	}
	out.text = strings.Join(texts, "\n")
	return out
}

// ---- Devin payload ----

type devinTool struct {
	Name, Description string
	Parameters        json.RawMessage
}

type devinPayload struct {
	system    string
	messages  []chatMsg
	tools     []devinTool
	selector  string
	maxTokens int
}

// Upstream selectors encode effort in the name (swe-2-medium/high/max), but
// the OpenAI surface exposes effort as a parameter. effortVariants lists the
// effort tiers each family actually ships; families absent here ignore effort
// and the name passes through verbatim.
var effortVariants = map[string][]string{
	"swe-2": {"medium", "high", "max"},
}

var familyDefaultEffort = map[string]string{
	"swe-2": "medium",
}

// Aliases keyed on the NORMALIZED (lowercase, dots→dashes) form.
var familyAliases = map[string]string{
	"swe2":    "swe-2",
	"swe-2-0": "swe-2",
}

// Tier order used to clamp an unsupported effort to the nearest real variant.
// Out-of-range requests prefer the closest HIGHER tier, then lower.
var effortTiers = []string{"none", "minimal", "low", "medium", "high", "xhigh", "max"}

func tierIndex(s string) int {
	for i, t := range effortTiers {
		if t == s {
			return i
		}
	}
	return -1
}

func nearestVariant(effort string, variants []string) string {
	want := tierIndex(effort)
	if want < 0 {
		want = tierIndex("medium")
	}
	have := map[string]bool{}
	for _, v := range variants {
		have[v] = true
	}
	for d := 0; d < len(effortTiers); d++ {
		if hi := want + d; hi < len(effortTiers) && have[effortTiers[hi]] {
			return effortTiers[hi]
		}
		if lo := want - d; lo >= 0 && have[effortTiers[lo]] {
			return effortTiers[lo]
		}
	}
	return variants[0]
}

func isEffortSuffix(s string) bool { return tierIndex(s) >= 0 }

// resolveSelector maps (model, reasoning_effort) onto the upstream selector.
// Priority: explicit effort suffix in the model name ("swe-2-high") >
// reasoning_effort parameter > family default. Names outside the effort
// registry pass through verbatim (e.g. swe-1-6-fast, claude-opus-4-8-medium).
func resolveSelector(model, effort string) string {
	m := strings.ToLower(strings.TrimSpace(model))
	if m == "" {
		if d := os.Getenv("DEVIN_DEFAULT_MODEL"); d != "" {
			m = strings.ToLower(strings.ReplaceAll(d, ".", "-"))
		} else {
			m = defaultUpstreamModel
		}
	}
	m = strings.ReplaceAll(m, ".", "-")
	if a, ok := familyAliases[m]; ok {
		m = a
	}
	base := m
	suffixEffort := ""
	if i := strings.LastIndex(m, "-"); i >= 0 && isEffortSuffix(m[i+1:]) {
		suffixEffort = m[i+1:]
		base = m[:i]
		if a, ok := familyAliases[base]; ok {
			base = a
		}
	}
	if variants, ok := effortVariants[base]; ok {
		pick := suffixEffort
		if pick == "" {
			pick = effort
		}
		if pick == "" {
			pick = familyDefaultEffort[base]
		}
		if pick == "" {
			pick = variants[0]
		}
		return base + "-" + nearestVariant(pick, variants)
	}
	return m // verbatim passthrough (unregistered family or foreign selector)
}

// toDevinPayload maps OpenAI messages to Devin history. Signature rehydration:
// for every assistant turn we consult sigStore — first by reasoning text (the
// client echoed reasoning_content), then by assistant text+tool_calls digest.
// A miss simply leaves the turn unsigned (swe family tolerates; signed-required
// families like claude-opus would 400 — surfaced as an upstream error).
func toDevinPayload(req *chatRequest, store *sigStore) *devinPayload {
	selector := resolveSelector(req.Model, req.effort())
	maxTok := req.MaxCompToks
	if maxTok == 0 {
		maxTok = req.MaxTokens
	}
	p := &devinPayload{selector: selector, maxTokens: maxTok}

	var sysParts []string
	var msgs []chatMsg
	for _, m := range req.Messages {
		switch m.Role {
		case "system", "developer":
			if t := flattenContent(m.Content).text; t != "" {
				sysParts = append(sysParts, t)
			}
			continue
		case "user":
			c := flattenContent(m.Content)
			msgs = append(msgs, chatMsg{source: 1, text: c.text, images: c.images})
		case "assistant":
			c := flattenContent(m.Content)
			am := chatMsg{source: 2, text: c.text}
			for _, tc := range m.ToolCalls {
				am.toolCalls = append(am.toolCalls, chatToolCall{
					ID:   tc.ID,
					Name: tc.Function.Name,
					Args: tc.Function.Arguments,
				})
			}
			// Rehydrate the signed thinking blob. Two keys: the reasoning the
			// client echoed, and the assistant content itself (when the client
			// strips reasoning_content entirely).
			var blob *SignedThinking
			if m.ReasoningContent != "" {
				blob = store.get(digestOf("reasoning", m.ReasoningContent), selector)
			}
			if blob == nil {
				blob = store.get(digestOf("assistant", c.text, toolCallDigest(am.toolCalls)), selector)
			}
			am.thinking = blob
			if c.text == "" && len(am.toolCalls) == 0 && blob == nil {
				continue // drop empty assistant turns (upstream rejects them)
			}
			msgs = append(msgs, am)
		case "tool":
			c := flattenContent(m.Content)
			msgs = append(msgs, chatMsg{
				source:     4,
				text:       firstNonEmpty(c.text, "[tool result]"),
				toolCallID: m.ToolCallID,
			})
		}
	}

	p.system = strings.Join(sysParts, "\n")
	p.messages = mergeSameSource(msgs)
	for _, t := range req.Tools {
		if t.Type != "" && t.Type != "function" {
			continue
		}
		p.tools = append(p.tools, devinTool{
			Name:        t.Function.Name,
			Description: t.Function.Description,
			Parameters:  t.Function.Parameters,
		})
	}
	return p
}

func toolCallDigest(calls []chatToolCall) string {
	var b strings.Builder
	for _, c := range calls {
		fmt.Fprintf(&b, "%s\x00%s\x00%s\x00", c.ID, c.Name, c.Args)
	}
	return b.String()
}

func firstNonEmpty(s, fallback string) string {
	if s == "" {
		return fallback
	}
	return s
}

// Upstream rejects a run of >=3 consecutive same-source text messages; merge.
func mergeSameSource(in []chatMsg) []chatMsg {
	var out []chatMsg
	for _, m := range in {
		if len(out) > 0 {
			prev := &out[len(out)-1]
			if prev.source == m.source &&
				len(prev.toolCalls) == 0 && len(m.toolCalls) == 0 &&
				prev.thinking == nil && m.thinking == nil &&
				prev.toolCallID == "" && m.toolCallID == "" &&
				len(prev.images) == 0 && len(m.images) == 0 {
				prev.text = strings.TrimSpace(prev.text + "\n\n" + m.text)
				continue
			}
		}
		out = append(out, m)
	}
	return out
}

// Conversation identity for #16 cascade_id / trajectory / session: stable per
// conversation root so the upstream sees one continuous session.
func convKey(req *chatRequest, p *devinPayload) string {
	var root string
	for _, m := range req.Messages {
		if m.Role == "user" {
			root = flattenContent(m.Content).text
			break
		}
	}
	return digestOf(p.selector, p.system, root)
}

package main

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sync"
	"time"
)

// SignedThinking is one upstream-issued reasoning block: the thinking text plus
// the opaque signature the server uses to verify/continue the trace on the next
// turn (ChatMessage #11/#12/#13/#18). The proxy never decrypts it — it just
// round-trips the blob so multi-turn requests keep a verified CoT.
type SignedThinking struct {
	Text      string
	Signature string
	SigType   string // "sealed" / "non-sealed" / ...
	Redacted  bool
	Selector  string // upstream model selector that issued it
	StoredAt  time.Time
}

// sigStore rehydrates signatures on rebuilt history. The client only has to
// echo either the assistant TEXT or the reasoning_content verbatim — the blob
// is indexed under both digests. A forked/edited turn simply misses and rides
// unsigned, which the swe family tolerates.
type sigStore struct {
	mu   sync.Mutex
	m    map[string]*SignedThinking
	keys []string // FIFO eviction
	max  int
	ttl  time.Duration
}

func newSigStore(max int, ttl time.Duration) *sigStore {
	return &sigStore{m: make(map[string]*SignedThinking), max: max, ttl: ttl}
}

func (s *sigStore) put(key string, t *SignedThinking) {
	if key == "" || t == nil || t.Signature == "" {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.m[key]; !ok {
		s.keys = append(s.keys, key)
		for len(s.keys) > s.max {
			delete(s.m, s.keys[0])
			s.keys = s.keys[1:]
		}
	}
	s.m[key] = t
}

func (s *sigStore) get(key, selector string) *SignedThinking {
	s.mu.Lock()
	defer s.mu.Unlock()
	t := s.m[key]
	if t == nil {
		return nil
	}
	if s.ttl > 0 && time.Since(t.StoredAt) > s.ttl {
		return nil
	}
	// Audit rule (pi-devin): only replay a signature to the same upstream
	// selector that issued it — cross-model replay is refused.
	if selector != "" && t.Selector != "" && t.Selector != selector {
		return nil
	}
	return t
}

func digestOf(parts ...string) string {
	h := sha256.New()
	for _, p := range parts {
		fmt.Fprintf(h, "%d\x00%s\x00", len(p), p)
	}
	return hex.EncodeToString(h.Sum(nil))
}
